<?php require_once "../config/auth.php";requireAdmin();require_once "../config/database.php";$msg="";if($_SERVER["REQUEST_METHOD"]==="POST"){$n=trim($_POST["club_name"]);$d=trim($_POST["description"]);$co=trim($_POST["coordinator"]);$cat=(int)$_POST["category_id"];$s=$conn->prepare("INSERT INTO clubs(club_name,category_id,description,coordinator) VALUES(?,?,?,?)");$s->bind_param("siss",$n,$cat,$d,$co);$s->execute();$msg="Club added successfully!";}$cats=$conn->query("SELECT * FROM categories ORDER BY category_name");?><!DOCTYPE html><html><head><title>Add Club</title><link rel="stylesheet" href="../css/style.css"></head><body><nav class="navbar"><div class="logo">Admin</div><div class="nav-links"><a href="dashboard.php">Dashboard</a><a href="../logout.php">Logout</a></div></nav><div class="form-wrap"><div class="form-box"><h2>Add New Club</h2><?php if($msg):?><div class="alert"><?=$msg?></div><?php endif;?><form method="post"><label>Club Name</label><input name="club_name" required><label>Category</label><select name="category_id"><?php while($c=$cats->fetch_assoc()):?><option value="<?=$c["category_id"]?>"><?=htmlspecialchars($c["category_name"])?></option><?php endwhile;?></select><label>Description</label><textarea name="description" required></textarea><label>Coordinator</label><input name="coordinator" required><button class="btn full">Add Club</button></form></div></div></body></html>